// ---------- the game-form methods from chapter 9 ----------

// Keeps the result on the map, even if the window is then closed
private void KeepResult()
{
    Expedition.Finish(gameNumber, result);
    finished = true;
    lblScore.Text = "Points: " + result.Score;
}

// Fills in the Round over panel and brings it to the front
private void ShowRoundOver()
{
    lblRoundScore.Text = "You scored " + result.Score
        + " out of 100 points.";
    lblWellList.Text = ListText(result.WentWell,
        "thing that went well", "things that went well");
    lblWrongList.Text = ListText(result.WentWrong,
        "thing that went wrong", "things that went wrong");
    if (result.Score >= 60) Sound.Play("win.wav");
    else Sound.Play("lose.wav");
    pnlRoundOver.Visible = true;
    pnlRoundOver.BringToFront();
}

// Up to 3 lines from a list, then how many more there are
private string ListText(List<string> lines, string one, string many)
{
    if (lines.Count == 0) return "Nothing this time.";
    string text = "";
    for (int i = 0; i < lines.Count && i < 3; i++)
    {
        text = text + "- " + lines[i] + Environment.NewLine;
    }
    int more = lines.Count - 3;
    if (more == 1) text = text + "And 1 more " + one + ".";
    if (more > 1) text = text + "And " + more + " more " + many + ".";
    return text;
}

// Back to the map: closing the window runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// The Round over panel's Back to the map button
private void btnDone_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the window closes, by Back, by Done or by the X
private void frmLitter_FormClosing(object sender,
    FormClosingEventArgs e)
{
    if (finished) return;    // a finished round closes at once
    DialogResult answer = MessageBox.Show("Leave Leave No Trace? It "
        + "will score nothing, but you can come back and climb it "
        + "again.", "Summit Ready", MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

// ---------- Leave No Trace ----------
private string[] litterFiles = { "litter-beverage-box.png",
    "litter-canned-food.png", "litter-cup-with-straw.png",
    "litter-newspaper.png", "litter-red-apple.png",
    "litter-shopping-bags.png", "litter-sweet.png" };
private PictureBox[] litter = new PictureBox[8];
private PictureBox[] sheep = new PictureBox[3];
private int[] dx = { 3, -2, 2 };     // each sheep's step across
private int[] dy = { 2, 3, -3 };     // each sheep's step down
private PictureBox[] hearts = new PictureBox[3];
private Image heart;
private Image greyHeart;             // a faded copy of the heart

private bool goUp, goDown, goLeft, goRight;   // keys held down
private int got = 0;                 // litter picked up
private int bumps = 0;               // times a sheep knocked you over
private int secondsLeft = 45;
private int safeTicks = 0;           // 75 ticks of 20 ms is 1.5 s
private Random random = new Random();

private void frmLitter_Load(object sender, EventArgs e)
{
    // Runs once, right before the window first appears
    ShowSpeaker();
    pnlField.BackgroundImage = Files.Picture("", "field.jpg");
    picPlayer.Image = Files.Picture("Avatars",
        Expedition.CurrentPlayer.Avatar);
    heart = Files.Picture("Icons", "icon-heart-64.png");
    if (heart != null)
    {
        greyHeart = ToolStripRenderer.CreateDisabledImage(heart);
    }
    hearts[0] = picHeart1;
    hearts[1] = picHeart2;
    hearts[2] = picHeart3;
    foreach (PictureBox h in hearts) h.Image = heart;
    PlaceLitter();
    PlaceSheep();
    btnGo.BringToFront();
}

// 8 pieces of litter at random places, away from the start point
private void PlaceLitter()
{
    Point start = picPlayer.Location;
    for (int i = 0; i < 8; i++)
    {
        PictureBox piece = new PictureBox();
        piece.Size = new Size(40, 40);
        piece.SizeMode = PictureBoxSizeMode.Zoom;
        piece.BackColor = Color.Transparent;
        piece.Image = Files.Picture("Litter", litterFiles[i % 7]);
        int x = 0;
        int y = 0;
        bool tooClose = true;
        while (tooClose)
        {
            x = random.Next(0, pnlField.Width - 40);
            y = random.Next(0, pnlField.Height - 40);
            int across = Math.Abs(x - start.X);
            int down = Math.Abs(y - start.Y);
            bool underStrip = x > pnlStrip.Left - 40
                && y < pnlStrip.Bottom;
            tooClose = (across < 120 && down < 120) || underStrip;
        }
        piece.Location = new Point(x, y);
        litter[i] = piece;
        pnlField.Controls.Add(piece);
    }
}

// 3 sheep, each starting in a different part of the field
private void PlaceSheep()
{
    Point[] starts = { new Point(300, 90), new Point(620, 300),
        new Point(820, 460) };
    for (int i = 0; i < 3; i++)
    {
        PictureBox one = new PictureBox();
        one.Size = new Size(64, 64);
        one.SizeMode = PictureBoxSizeMode.Zoom;
        one.BackColor = Color.Transparent;
        one.Image = Files.Picture("Litter", "sheep.png");
        one.Location = starts[i];
        sheep[i] = one;
        pnlField.Controls.Add(one);
    }
}

// Start walking: the button hides, so no button takes the arrows
private void btnGo_Click(object sender, EventArgs e)
{
    btnGo.Visible = false;
    btnBack.Enabled = false;
    this.Focus();
    tmrGame.Start();
    tmrClock.Start();
}

// A key pressed: the arrows or W A S D set a flag
private void frmLitter_KeyDown(object sender, KeyEventArgs e)
{
    // A quick tap still moves one step, even between two ticks
    bool wasStill = !goUp && !goDown && !goLeft && !goRight;
    if (e.KeyCode == Keys.Up || e.KeyCode == Keys.W) goUp = true;
    if (e.KeyCode == Keys.Down || e.KeyCode == Keys.S) goDown = true;
    if (e.KeyCode == Keys.Left || e.KeyCode == Keys.A) goLeft = true;
    if (e.KeyCode == Keys.Right || e.KeyCode == Keys.D) goRight = true;
    if (wasStill && tmrGame.Enabled) MovePlayer();
}

// A key let go: its flag is cleared
private void frmLitter_KeyUp(object sender, KeyEventArgs e)
{
    if (e.KeyCode == Keys.Up || e.KeyCode == Keys.W) goUp = false;
    if (e.KeyCode == Keys.Down || e.KeyCode == Keys.S) goDown = false;
    if (e.KeyCode == Keys.Left || e.KeyCode == Keys.A) goLeft = false;
    if (e.KeyCode == Keys.Right || e.KeyCode == Keys.D)
    {
        goRight = false;
    }
}

// Every 20 ms: move the player, move the sheep, check for hits
private void tmrGame_Tick(object sender, EventArgs e)
{
    MovePlayer();
    MoveSheep();
    CheckLitter();
    CheckSheep();
}

// Moves the player 6 px for each key held, kept inside the field
private void MovePlayer()
{
    if (goUp && picPlayer.Top > 0) picPlayer.Top -= 6;
    if (goDown && picPlayer.Bottom < pnlField.Height)
    {
        picPlayer.Top += 6;
    }
    if (goLeft && picPlayer.Left > 0) picPlayer.Left -= 6;
    if (goRight && picPlayer.Right < pnlField.Width)
    {
        picPlayer.Left += 6;
    }
}

// Moves each sheep; a sheep turns round at an edge
private void MoveSheep()
{
    for (int i = 0; i < 3; i++)
    {
        sheep[i].Left += dx[i];
        sheep[i].Top += dy[i];
        if (sheep[i].Left < 0 || sheep[i].Right > pnlField.Width)
        {
            dx[i] = -dx[i];
        }
        if (sheep[i].Top < 0 || sheep[i].Bottom > pnlField.Height)
        {
            dy[i] = -dy[i];
        }
    }
}

// Touching a piece of litter picks it up
private void CheckLitter()
{
    foreach (PictureBox piece in litter)
    {
        if (piece.Visible
            && picPlayer.Bounds.IntersectsWith(piece.Bounds))
        {
            piece.Visible = false;
            got++;
            lblGot.Text = "Litter picked up: " + got + " of 8";
            Sound.Play("pickup.wav");
            if (got == 8) EndRound();
        }
    }
}

// Touching a sheep loses a life, then 1.5 seconds of safety
private void CheckSheep()
{
    if (finished) return;
    if (safeTicks > 0)
    {
        safeTicks--;
        picPlayer.Visible = safeTicks % 10 < 5 || safeTicks == 0;
        return;
    }
    foreach (PictureBox one in sheep)
    {
        if (picPlayer.Bounds.IntersectsWith(one.Bounds))
        {
            hearts[bumps].Image = greyHeart;
            bumps++;
            Sound.Play("bump.wav");
            safeTicks = 75;
            if (bumps == 3) EndRound();
            return;
        }
    }
}

// Every second: one less second; at 0 the round ends
private void tmrClock_Tick(object sender, EventArgs e)
{
    secondsLeft--;
    lblTime.Text = "Seconds left: " + secondsLeft;
    if (secondsLeft == 0) EndRound();
}

// Stops the play, keeps the result, then waits 0.9 seconds
private void EndRound()
{
    if (finished) return;          // the round can only end once
    tmrGame.Stop();
    tmrClock.Stop();
    picPlayer.Visible = true;
    btnBack.Enabled = true;
    RecordResult();
    tmrDone.Start();
}

// Runs 0.9 seconds after the end: the Round over panel opens
private void tmrDone_Tick(object sender, EventArgs e)
{
    tmrDone.Stop();
    ShowRoundOver();
}

// Works out the score, adds the feedback, then keeps the result
private void RecordResult()
{
    int bonus = 0;
    if (got == 8) bonus = secondsLeft;
    if (bonus > 20) bonus = 20;
    result = new GameResult("Leave No Trace", got * 10 + bonus);
    AddFeedback();
    KeepResult();
}

// Writes what went well and what went wrong into the result
private void AddFeedback()
{
    if (got == 8)
    {
        result.WentWell.Add("You picked up all 8 pieces of litter.");
        result.WentWell.Add("Seconds to spare: " + secondsLeft + ".");
    }
    else if (got > 0)
    {
        result.WentWell.Add("You picked up " + Pieces(got)
            + " of litter.");
    }
    if (bumps == 0) result.WentWell.Add("No sheep knocked you over.");
}

// Writes what went well and what went wrong into the result
private void AddFeedback()
{
    if (got == 8)
    {
        result.WentWell.Add("You picked up all 8 pieces of litter.");
        result.WentWell.Add("Seconds to spare: " + secondsLeft + ".");
    }
    else if (got > 0)
    {
        result.WentWell.Add("You picked up " + Pieces(got)
            + " of litter.");
    }
    if (bumps == 0) result.WentWell.Add("No sheep knocked you over.");
    if (bumps == 3)
    {
        result.WentWrong.Add("A sheep knocked you over three times.");
    }
    else if (got < 8)
    {
        result.WentWrong.Add("Time ran out before the hill was "
            + "clean.");
    }
    if (got < 8)
    {
        result.WentWrong.Add("You left " + Pieces(8 - got)
            + " of litter on the hill.");
    }
    if (bumps == 1)
    {
        result.WentWrong.Add("A sheep knocked you over once.");
    }
    if (bumps == 2)
    {
        result.WentWrong.Add("A sheep knocked you over 2 times.");
    }
}

// "1 piece" or "3 pieces", so the number always has its thing
private string Pieces(int count)
{
    if (count == 1) return "1 piece";
    return count + " pieces";
}
